inputs.javascriptFunction:
return {
  component: "Chat Input",
  role: "flowise_managed",
  question: $input?.question || $input || "",
  input: $input
};

const input = $input || {};
return {
  ...input,
  component: "Flowise Workflow Configuration",
  role: "flowise_managed_control_plane",
  stage_config: {
    document_upload: {
      enabled: $vars?.upload_enabled !== "false",
      required_documents: ($vars?.required_documents || "bank_statement,payslip,collateral_valuation").split(",").map(x => x.trim()).filter(Boolean),
      allowed_file_types: ($vars?.allowed_file_types || "pdf,docx,xlsx,csv,png,jpg,jpeg,txt").split(",").map(x => x.trim()).filter(Boolean),
      max_file_count: Number($vars?.max_file_count || 10)
    },
    parser: {
      enabled: $vars?.parser_enabled !== "false",
      mode: $vars?.parser_mode || "ocr_tables",
      language: input.language || "en",
      strict_mode: $vars?.parser_strict_mode !== "false"
    },
    chunker: {
      enabled: $vars?.chunker_enabled !== "false",
      chunk_size: Number($vars?.chunk_size || 800),
      chunk_overlap: Number($vars?.chunk_overlap || 120),
      strategy: $vars?.chunk_strategy || "by_section_then_page",
      max_chunks: Number($vars?.max_chunks || 500)
    },
    embeddings: {
      enabled: $vars?.embeddings_enabled !== "false",
      provider: $vars?.embedding_provider || "local",
      model: $vars?.embedding_model || "nomic-embed-text",
      batch_size: Number($vars?.embedding_batch_size || 32),
      reembed: $vars?.reembed === "true"
    },
    postgresql: {
      enabled: true,
      storage_profile: $vars?.storage_profile || "default_credit_appraisal",
      schema: $vars?.db_schema || "public",
      retention_days: Number($vars?.retention_days || 365)
    },
    pgvector: {
      enabled: true,
      index_profile: $vars?.vector_index_profile || "credit_documents_v1",
      similarity_metric: $vars?.similarity_metric || "cosine",
      score_threshold: Number($vars?.score_threshold || 0.72)
    },
    retrieval: {
      enabled: true,
      top_k: Number($vars?.top_k || 8),
      document_types: ($vars?.retrieval_document_types || "bank_statement,payslip,collateral_valuation,policy").split(",").map(x => x.trim()).filter(Boolean),
      customer_scope: $vars?.customer_scope || "customer_only",
      include_policy_context: $vars?.include_policy_context !== "false"
    },
    policy_score: {
      enabled: $vars?.policy_score_enabled !== "false",
      policy_mode: input.policy_mode || "standard_credit_policy",
      product_type: $vars?.product_type || "generic_credit",
      dti_warning_threshold: Number($vars?.dti_warning_threshold || 0.35),
      dti_reject_threshold: Number($vars?.dti_reject_threshold || 0.45),
      ltv_warning_threshold: Number($vars?.ltv_warning_threshold || 0.70),
      ltv_reject_threshold: Number($vars?.ltv_reject_threshold || 0.85)
    },
    audit: {
      enabled: $vars?.audit_enabled !== "false",
      level: $vars?.audit_level || "full"
    }
  }
};

const input = $input || {};
return {
  ...input,
  component: "Document Upload",
  role: "flowise_managed_fastapi_executed",
  stage: "document_upload",
  enabled: input.stage_config?.document_upload?.enabled ?? true,
  method: "POST",
  endpoint: `${input.backend_base_url}/documents/upload`,
  expected_form_fields: {
    customer_id: input.customer_id,
    session_id: input.session_id,
    source: "flowise",
    file: "<uploaded file>"
  },
  config: input.stage_config?.document_upload || {}
};

const input = $input || {};
const retrievalConfig = input.stage_config?.retrieval || {};
return {
  ...input,
  component: "FAST API Stages: Retrieval → Retriever",
  role: "flowise_managed_fastapi_executed",
  stage_group: "retrieval",
  method: "POST",
  endpoint: `${input.backend_base_url}/retrieval/query`,
  body: {
    customer_id: input.customer_id,
    session_id: input.session_id,
    question: input.question,
    top_k: retrievalConfig.top_k || 8,
    filters: {
      policy_mode: input.policy_mode,
      document_types: retrievalConfig.document_types || [],
      score_threshold: input.stage_config?.pgvector?.score_threshold || 0.72,
      customer_scope: retrievalConfig.customer_scope || "customer_only",
      include_policy_context: retrievalConfig.include_policy_context ?? true
    }
  },
  evidence: input.evidence || [],
  missing_documents: input.missing_documents || []
};

const input = $input || {};
const evidence = input.evidence || input.retrieved_evidence || [];
const citations = evidence.map((item, idx) => ({
  citation_id: `C${idx + 1}`,
  document_id: item.document_id || null,
  chunk_id: item.chunk_id || null,
  document_name: item.document_name || "Unknown document",
  page: item.page || null,
  score: item.score || null,
  source_type: item.source_type || "customer_document",
  text: item.text || ""
}));
const citation_text = citations.map(c => {
  const pageText = c.page ? `p.${c.page}` : "page unknown";
  return `[${c.citation_id}] ${c.document_name}, ${pageText}: ${c.text}`;
}).join("\n\n");
return {
  ...input,
  component: "Citation Builder",
  role: "flowise_managed",
  citations,
  citation_text,
  citation_chunk_ids: citations.map(c => c.chunk_id).filter(Boolean),
  missing_documents: input.missing_documents || []
};

const input = $input || {};
const policyConfig = input.stage_config?.policy_score || {};
return {
  ...input,
  component: "FAST API Stages: Policy Score → DTI → LTV → Rate → Payment → Recommendation",
  role: "flowise_managed_fastapi_executed",
  stage_group: "policy_scoring",
  method: "POST",
  endpoint: `${input.backend_base_url}/loan-policy/score`,
  body: {
    customer_id: input.customer_id,
    session_id: input.session_id,
    policy_mode: policyConfig.policy_mode || input.policy_mode,
    product_type: policyConfig.product_type || "generic_credit",
    question: input.question,
    evidence: input.citations || [],
    thresholds: {
      dti_warning_threshold: policyConfig.dti_warning_threshold,
      dti_reject_threshold: policyConfig.dti_reject_threshold,
      ltv_warning_threshold: policyConfig.ltv_warning_threshold,
      ltv_reject_threshold: policyConfig.ltv_reject_threshold
    }
  },
  policy_score: input.policy_score || {
    dti: input.dti || null,
    ltv: input.ltv || null,
    interest_rate: input.interest_rate || null,
    monthly_payment: input.monthly_payment || null,
    risk_level: input.risk_level || "unknown",
    recommendation: input.recommendation || "human_review_required",
    human_review_required: true
  }
};

const input = $input || {};
const provider = (input.llm_provider || "ollama").toLowerCase();
const accepted = ["ollama", "openai", "deepseek", "custom"];
return {
  ...input,
  component: "LLM Router",
  role: "flowise_managed",
  route_mode: "single_selectable_provider",
  selected_provider: accepted.includes(provider) ? provider : "ollama",
  selected_model: input.llm_model || "mistral",
  provider_options: {
    ollama: { enabled: true, local_private: true, base_url: $vars?.ollama_base_url || "http://host.docker.internal:11434" },
    openai: { enabled: $vars?.openai_enabled === "true", secure_config: "env_vars" },
    deepseek: { enabled: $vars?.deepseek_enabled === "true", secure_config: "env_vars" },
    custom: { enabled: $vars?.custom_provider_enabled === "true", secure_config: "env_vars" }
  }
};

const input = $input || {};
return {
  ...input,
  component: "FAST API Stages: Approval Committee → Final Decision → Customer Email Draft",
  role: "fastapi_execution_card_optional",
  managed_by_flowise: true,
  executed_by_fastapi: true,
  human_review_required: true,
  stage_group: "human_decision_workflow",
  endpoints: {
    approval_committee: `${input.backend_base_url || "http://host.docker.internal:8000"}/approval-committee/submit`,
    final_decision: `${input.backend_base_url || "http://host.docker.internal:8000"}/final-decision`,
    customer_email_draft: `${input.backend_base_url || "http://host.docker.internal:8000"}/customer-decision-email/draft`
  },
  note: "LISA never approves or rejects loans. These stages are human/backend workflow stages only."
};

const input = $input || {};
return {
  component: "Chat Output",
  role: "flowise_managed",
  answer: input.raw_answer || input.answer || input.text || input,
  human_review_required: true,
  footer: "Human credit officer review required."
};
